const callbacks=new Map();let req=0;
window.nativeResult=(id,data,error)=>{const c=callbacks.get(id);if(!c)return;callbacks.delete(id);clearTimeout(c.timeout);error?c.reject(Error(error)):c.resolve(data)};
const isNative=!!window.Android;
let mockData;try{mockData=JSON.parse(localStorage.getItem('kitapligim-preview')||'null')}catch{}
if(!mockData)mockData={version:1,books:[],profile:'Güleser',goals:{},connected:false,lastSync:'',syncError:'',assistant:{configured:false,url:'',altUrl:''}};
async function native(action,p={}){
  if(isNative)return new Promise((resolve,reject)=>{const id=String(++req);const timeout=setTimeout(()=>{callbacks.delete(id);reject(Error('İşlem uzun sürdü. Kaydı kontrol ederek yeniden dene.'))},180000);callbacks.set(id,{resolve,reject,timeout});Android.request(id,action,JSON.stringify(p))});
  // Local browser preview adapter. Android always uses its private native storage above.
  const persist=()=>{localStorage.setItem('kitapligim-preview',JSON.stringify(mockData));return structuredClone(mockData)};
  switch(action){case'state':return persist();case'settings':if(p.profile)mockData.profile=p.profile;if(p.goal)mockData.goals[mockData.profile]=p.goal;return persist();case'save':{const b={...p,id:p.id||uid(),syncStatus:'pending',updatedAt:new Date().toISOString()};const i=mockData.books.findIndex(x=>x.id===b.id);if(i<0)mockData.books.push(b);else mockData.books[i]=b;return persist()}case'delete':{const b=mockData.books.find(x=>x.id===p.id);if(b)b.deleted=true;return persist()}case'connect':case'sync':throw Error('Notion bağlantısı Android uygulamasında kullanılabilir.');case'photo':throw Error('Kamera ve yazı okuma Android uygulamasında kullanılabilir.');case'search':{const normalize=x=>x.toLocaleLowerCase('tr').replace(/ı/g,'i').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ').trim();const words=normalize(p.q).split(/\s+/);const catalog=await fetch('catalog-tr.json').then(r=>r.json());const matches=catalog.filter(b=>words.every(w=>normalize(b.title+' '+b.author+' '+b.isbn).includes(w)));matches.sort((a,b)=>Number(normalize(b.title)===normalize(p.q))-Number(normalize(a.title)===normalize(p.q)));let remote=[];try{const r=await fetch('https://openlibrary.org/search.json?q='+encodeURIComponent(p.q)+'&limit=16&fields=title,author_name,cover_i,isbn,number_of_pages_median',{signal:AbortSignal.timeout(4000)});if(r.ok)remote=(await r.json()).docs.map(x=>({title:x.title,author:(x.author_name||[]).join(', '),isbn:x.isbn?.[0]||'',cover:x.cover_i?'https://covers.openlibrary.org/b/id/'+x.cover_i+'-M.jpg':'',totalPages:x.number_of_pages_median||0,source:'Open Library'}))}catch{}return [...matches,...remote]}case'disconnect':mockData.connected=false;return persist();case'resolve':{let b=mockData.books.find(x=>x.id===p.id);if(p.remote)Object.assign(b,b.conflictRemote,{id:b.id,syncStatus:'synced'});else b.syncStatus='pending';delete b.conflictRemote;return persist()}case'open':case'openLink':window.open(p.url,'_blank','noopener');return{};case'shopPrices':await new Promise(r=>setTimeout(r,600));return [];case'offers':return p.books.map(b=>b.isbn?{price:'',store:'D&R araması',buyUrl:'https://www.dr.com.tr/search?q='+encodeURIComponent(b.isbn),searchOnly:true}:{});case'export':{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(mockData,null,2)],{type:'application/json'}));a.download='Kitapligim.json';a.click();return{}}case'assistantSave':mockData.assistant={configured:true,url:p.url,altUrl:p.altUrl||''};return persist();case'assistantClear':mockData.assistant={configured:false,url:'',altUrl:''};return persist();case'assistantTest':return{ok:true};case'chat':{if(!mockData.assistant?.configured)throw Error("Kitap Danışmanı henüz kurulmadı. Ayarlar'dan PC sunucusunun adresini ve anahtarını gir.");await new Promise(r=>setTimeout(r,900));const last=p.messages[p.messages.length-1].content;return{reply:'(Önizleme yanıtı) “'+last.slice(0,60)+'” için aklıma şunlar geldi:',books:[{title:'Hizmetçi',author:'Freida McFadden',why:'Sürükleyici, hızlı ilerleyen bir psikolojik gerilim.',isbn:'9786256411302',totalPages:352,cover:'',source:'Önizleme',verified:true},{title:'Sessiz Hasta',author:'Alex Michaelides',why:'Sonu şaşırtan, tek oturuşta okunan bir gizem.',isbn:'',totalPages:0,cover:'',source:'Danışman',verified:false}]}}default:return{}}
}
function updateViewport(){const v=window.visualViewport;document.documentElement.style.setProperty('--viewport-height',Math.round(Math.min(innerHeight,v?.height||innerHeight))+'px');document.documentElement.style.setProperty('--viewport-top',Math.round(v?.offsetTop||0)+'px')}
window.addEventListener('resize',updateViewport);window.visualViewport?.addEventListener('resize',updateViewport);window.visualViewport?.addEventListener('scroll',updateViewport);updateViewport();
let S={books:[],profile:'Güleser',goals:{},connected:false,assistant:{configured:false}},screen='home',shelf='reading',libraryQuery='',searchQuery='',searchMode='find',results=[],searching=false,searchError='',pendingPhoto=null,editBook=null,selectedRating=0,toastTimer,modalName='',detailId=null,detailFrom='home',draft=null,chatBusy=false,chatError='',chatDraft='',offerToken=0;
const chatKey=p=>'kitapligim-chat-'+p;
function loadChat(p=S.profile){try{return JSON.parse(localStorage.getItem(chatKey(p))||'[]')}catch{return[]}}
function saveChat(messages,p=S.profile){try{localStorage.setItem(chatKey(p),JSON.stringify(messages.slice(-40)))}catch{}}
const app=document.getElementById('app'),modal=document.getElementById('modal');
window.receiveState=data=>{S=data;render()};
function profileBooks(profile=S.profile){return S.books.filter(b=>!b.deleted&&b.profile===profile)}
function conflicts(){return S.books.filter(b=>b.syncStatus==='conflict')}
function count(status,profile=S.profile){return profileBooks(profile).filter(b=>b.status===status).length}
function annual(profile=S.profile){const year=String(new Date().getFullYear());return profileBooks(profile).filter(b=>b.status==='done'&&(b.finishedAt||'').startsWith(year)).length}
function percent(b){return b.totalPages>0?Math.min(100,Math.round(b.currentPage/b.totalPages*100)):0}
function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4200)}
function avatar(p,cls=''){const i=PROFILES.indexOf(p);return `<span class="avatar ${cls}" style="--avatar:${COLORS[i][0]};--ink-a:${COLORS[i][1]}">${p[0]}</span>`}
function cover(b){let hash=0;for(const c of b.title||'')hash=(hash*31+c.charCodeAt(0))>>>0;const colors=[['#a6ad96','#fff9e8'],['#bd8f6e','#fff6de'],['#83939b','#f7f4e8'],['#b6a883','#fff8e8'],['#8f7e79','#faf4e4'],['#c4b898','#5a5442']];const c=colors[hash%colors.length];const image=b.localCover?(isNative?'https://appassets.androidplatform.net/covers/':'/covers/')+encodeURIComponent(b.localCover):b.cover;const safe=image&&/^https:\/\//.test(image);return `<div class="cover" style="--cover:${c[0]};--cover-ink:${c[1]}"><div class="cover-title">${esc(b.title)}</div><div class="cover-decoration"></div><div class="cover-author">${esc(b.author||'Kitaplığım')}</div>${safe?`<img src="${attr(image)}" alt="${attr(b.title)} kapağı" loading="lazy" referrerpolicy="no-referrer">`:''}</div>`}
function profiles(mini=false){return `<div class="profiles ${mini?'mini':''}" aria-label="Aile profilleri">${PROFILES.map(p=>`<button class="profile ${S.profile===p?'active':''}" aria-pressed="${S.profile===p}" aria-label="${p}" data-action="profile" data-profile="${p}">${avatar(p)}<span>${p}</span></button>`).join('')}</div>`}
function header(){if(screen==='home')return `<header class="topbar"><div class="wordmark">${icon('book')}<span>Kitaplığım</span></div><button class="icon-btn" data-action="settings" aria-label="Ayarlar">${icon('settings')}</button></header>`;return `<header class="topbar"><h1>${({search:'Kitap bul',stats:'Hedefler',settings:'Ayarlar'})[screen]||''}</h1></header>`}
function nav(){return `<nav class="bottom-nav" aria-label="Ana menü">${[['home','book','Kitaplığım'],['search','search','Ara'],['stats','target','Hedefler'],['settings','settings','Ayarlar']].map(([id,ic,label])=>`<button class="nav-item ${screen===id?'active':''}" data-action="nav" data-screen="${id}" ${screen===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span></button>`).join('')}</nav>`}
function stars(n){return n>0?`<div class="stars" aria-label="5 üzerinden ${n} puan">${'★'.repeat(n)}${'☆'.repeat(5-n)}</div>`:''}
function bookRow(b,mode=''){const open=`data-action="detail" data-id="${attr(b.id)}"`,author=`<div class="author">${esc(b.author||'Yazar belirtilmedi')}</div>`;
  if(mode==='reading')return `<article class="card book-row"><button class="row-cover" ${open} aria-label="${attr(b.title)} ayrıntıları">${cover(b)}</button><div class="row-info"><h3>${esc(b.title)}</h3>${author}<div class="pages">${b.currentPage||0}${b.totalPages?' / '+b.totalPages:''} sayfa</div>${b.totalPages?`<div class="progress"><span style="width:${percent(b)}%"></span></div>`:'<div style="height:12px"></div>'}<button class="btn" ${open}>İlerlemeyi güncelle</button></div></article>`;
  return `<button class="card book-row ${mode}" ${open}><div class="row-cover">${cover(b)}</div><div class="row-info"><h3>${esc(b.title)}</h3>${author}${b.syncStatus==='conflict'?'<span class="badge conflict">İki sürüm var</span>':stars(b.rating||0)}</div><span class="row-chevron">${icon('arrow')}</span></button>`}
function home(){const books=profileBooks();let list=books.filter(b=>b.status===shelf);const total=list.length;if(libraryQuery)list=list.filter(b=>(b.title+' '+b.author).toLocaleLowerCase('tr').includes(libraryQuery.toLocaleLowerCase('tr')));list.sort((a,b)=>(b.updatedAt||'').localeCompare(a.updatedAt||''));
  const goal=Number(S.goals?.[S.profile]||0),done=annual(),next=books.filter(b=>b.status==='want').sort((a,b)=>(a.updatedAt||'').localeCompare(b.updatedAt||''))[0];
  const emptyText={reading:['Şu an bir kitap okumuyorsun','Okuyacaklarından birini başlat ya da yeni bir kitap ekle.'],want:['Okuyacak kitap yok','Merak ettiğin kitapları buraya biriktir.'],done:['Henüz bitirdiğin kitap yok','Bitirdiğin kitaplar burada birikecek.'],paused:['Ara verdiğin kitap yok','Yarım bıraktığın kitaplar burada bekler.']}[shelf];
  return `${profiles()}<h1>Kitaplığım</h1><p class="subtitle">Bir sonraki sayfaya hazır mısın?</p><div class="filters" role="tablist">${['reading','want','done','paused'].map(id=>[id,STATUS[id]]).map(([id,name])=>`<button class="chip ${shelf===id?'active':''}" role="tab" aria-selected="${shelf===id}" data-action="shelf" data-shelf="${id}">${name}</button>`).join('')}</div>${total>6||libraryQuery?`<form id="library-search" class="search-box">${icon('search')}<input name="q" value="${attr(libraryQuery)}" placeholder="Bu rafta ara" aria-label="Bu rafta ara"><button aria-label="Ara">${icon('arrow')}</button></form>`:''}${conflicts().length?`<button class="note warn" data-action="settings" style="width:100%;text-align:left">${icon('alert')} ${conflicts().length} kitap iki yerde değişti. Sürümleri karşılaştır.</button>`:''}${list.length?list.map(b=>bookRow(b,shelf==='reading'?'reading':'')).join(''):libraryQuery?empty('Bulunamadı','Farklı bir kitap veya yazar adı dene.','search','Kitap ekle'):empty(emptyText[0],emptyText[1])}<button class="card goal-card" data-action="stats"><span class="goal-icon">${icon('book')}</span><span class="goal-body"><strong>${goal?new Date().getFullYear()+' okuma hedefim':'Okuma hedefi belirle'}</strong>${goal?`<span class="goal-count">${done} / ${goal} kitap</span><div class="progress"><span style="width:${Math.min(100,done/goal*100)}%"></span></div>`:'<span class="goal-count muted">Yıllık hedefin için dokun</span>'}</span><span class="row-chevron">${icon('arrow')}</span></button>${next&&shelf!=='want'?`<div class="section-head"><h2>Sıradaki kitabım</h2></div>${bookRow(next,'compact')}`:''}`}
function searchPage(){const seg=`<div class="segment" role="tablist"><button role="tab" aria-selected="${searchMode==='find'}" class="${searchMode==='find'?'active':''}" data-action="mode" data-mode="find">${icon('search')}Kitap ara</button><button role="tab" aria-selected="${searchMode==='ai'}" class="${searchMode==='ai'?'active':''}" data-action="mode" data-mode="ai">${icon('sparkle')}Danışman</button></div>`;return `${profiles(true)}${seg}${searchMode==='ai'?chatView():findView()}`}
function findView(){return `<form id="book-search" class="search-box">${icon('search')}<input name="q" value="${attr(searchQuery)}" placeholder="Hangi kitabı arıyorsun?" aria-label="Kitap adı, yazar veya ISBN" enterkeyhint="search" autocomplete="off"><button aria-label="Kitap ara" ${searching?'disabled':''}>${icon('arrow')}</button></form><div class="add-options"><button class="add-option" data-action="photo-options">${icon('camera')}<span>Kapak fotoğrafı</span></button><button class="add-option" data-action="photo-options">${icon('barcode')}<span>ISBN tara</span></button></div>${pendingPhoto?'<div class="note">Fotoğrafın hazır. Kitabı bulup seçtiğinde kapak fotoğrafı da eklenecek.</div>':''}${searching?'<div class="loading">Kitaplar aranıyor…</div>':searchError?`<div class="note warn">${esc(searchError)}</div>`:results.length?`<div class="section-head"><h2>Arama sonuçları</h2><span class="muted">${results.length} sonuç</span></div>${results.map((b,i)=>`<button class="card result" data-action="select-result" data-index="${i}"><div class="result-cover">${cover(b)}</div><div class="result-info"><h3>${esc(b.title)}</h3><p>${esc(b.author||'Yazar belirtilmedi')}</p><small>${b.totalPages?b.totalPages+' sayfa · ':''}${esc(b.source)}</small>${b.price?`<div class="price-tag">${icon('cart')}${esc(b.price)}<span>${esc(b.store||'')}</span></div>`:b.offerPending?'<div class="price-tag pending">Fiyat aranıyor…</div>':''}</div><span class="add-circle">${icon('plus')}</span></button>`).join('')}<div class="note">Baskılara göre kapak ve sayfa sayısı değişebilir. Kaydederken kontrol edebilirsin.</div>`:searchQuery?empty('Bu aramada kitap bulunamadı','Kitap adını kısaltarak veya yazar adıyla tekrar ara. İstersen Danışman’a anlat ya da elle ekle.','manual','Elle ekle'):`<div class="panel"><h3>${icon('book')}Rafına üç yoldan ekle</h3><p>Adını yazıp bul, kapağını ya da barkodunu fotoğrafla, ya da Danışman’a kitabı anlat. Her kitap seçili profile kaydedilir.</p></div>`}<button class="btn outline full" style="margin-top:14px" data-action="manual">${icon('edit')}Elle kitap ekle</button>`}
function chatBubble(m,mi){if(m.role==='user')return `<div class="bubble user">${esc(m.content)}</div>`;return `<div class="bubble bot">${esc(m.content)}${(m.books||[]).map((b,bi)=>`<div class="rec"><div class="rec-cover">${cover(b)}</div><div style="min-width:0;flex:1"><h4>${esc(b.title)}</h4><div class="author">${esc(b.author)}</div><p class="why">${esc(b.why)}</p>${b.verified===false?'<span class="badge warn">Kataloglarda doğrulanamadı</span> ':''}<button class="btn small" data-action="rec-add" data-msg="${mi}" data-book="${bi}">${icon('plus')}Rafıma ekle</button></div></div>`).join('')}</div>`}
function chatView(){if(!S.assistant?.configured)return `<div class="panel"><h3>${icon('sparkle')}Kitap Danışmanı</h3><p>Ne okumak istediğini anlat, aklında kalan bir sahneyi tarif et; sana uygun kitapları bulsun. PC’deki Claude ile çalışır; bunun için PC sunucusunun adresini bir kez girmen gerekir.</p><button class="btn" data-action="assistant-setup">PC sunucusunu bağla</button></div>`;
  const msgs=loadChat(),ideas=[`${S.profile} için akşamları keyifle okunacak sıcak bir roman`,'Kısa ve sürükleyici bir psikolojik gerilim','Bir kadın başkasının evinde hizmetçi olarak çalışıyor, ev sahipleri tuhaf davranıyor… hangi kitaptı?'];
  return `${msgs.length||chatBusy?'':`<div class="panel"><h3>${icon('sparkle')}Ne okumak istersin?</h3><p>Bir ruh hali, bir tür ya da aklında kalan bir sahne anlat. Adını unuttuğun kitabı da birlikte bulalım.</p></div><div class="chat-ideas">${ideas.map(t=>`<button data-action="chat-idea" data-text="${attr(t)}">${esc(t)}</button>`).join('')}</div>`}<div class="chat-log">${msgs.map(chatBubble).join('')}${chatBusy?'<div class="bubble bot typing">Danışman düşünüyor</div>':''}${chatError?`<div class="bubble err">${esc(chatError)}<br><button class="tiny-link" data-action="chat-retry" style="margin-top:8px;color:inherit">Tekrar dene</button></div>`:''}</div>${msgs.length?'<button class="tiny-link" data-action="chat-clear" style="margin:12px auto 0">Sohbeti temizle</button>':''}<div class="chat-bar"><form id="chat-form" class="chat-form"><textarea name="m" rows="1" enterkeyhint="send" placeholder="Nasıl bir kitap arıyorsun?" aria-label="Danışmana yaz" maxlength="1500">${esc(chatDraft)}</textarea><button class="send" aria-label="Gönder">${icon('send')}</button></form></div>`}
function updateChat(){if(screen!=='search'||searchMode!=='ai')return;const had=!!document.activeElement?.closest?.('#chat-form');render();if(had){document.body.classList.add('typing');document.querySelector('.chat-form textarea')?.focus()}window.scrollTo(0,document.body.scrollHeight)}
async function requestChat(prof){chatBusy=true;chatError='';updateChat();try{const msgs=loadChat(prof),r=await native('chat',{profile:prof,library:profileBooks(prof).map(b=>({title:b.title,author:b.author,status:b.status,rating:b.rating||0})),messages:msgs.map(m=>({role:m.role,content:m.content}))});msgs.push({role:'assistant',content:r.reply,books:r.books||[]});saveChat(msgs,prof)}catch(e){chatError=e.message}finally{chatBusy=false;updateChat()}}
async function sendChat(text){text=String(text||'').trim();if(!text||chatBusy)return;const prof=S.profile,msgs=loadChat(prof);msgs.push({role:'user',content:text});saveChat(msgs,prof);chatDraft='';await requestChat(prof)}
function openDetail(id){const b=find(id);if(!b)return;if(b.syncStatus==='conflict'){conflict(b);return}detailFrom=screen==='detail'?detailFrom:screen;detailId=id;draft=null;navigate('detail');loadShopPrices(b,false)}
function dirty(){const b=find(detailId);return !!(draft&&b&&(draft.page!==(b.currentPage||0)||draft.rating!==(b.rating||0)||draft.notes!==(b.notes||'')))}
function leaveDetail(){if(dirty())showSheet('Kaydedilmeyen değişiklikler var','<p class="note">Sayfa, puan veya notlarındaki değişiklikler kaydedilmedi.</p>','<button class="btn secondary" data-action="close">Düzenlemeye dön</button><button class="btn" data-action="leave-now">Kaydetmeden çık</button>','leave');else{draft=null;navigate(detailFrom)}}
function updateDetailProgress(){const b=find(detailId),bar=document.querySelector('.page-card .progress span');if(b&&bar&&b.totalPages)bar.style.width=Math.min(100,Math.round((draft.page||0)/b.totalPages*100))+'%'}
function highlightsCard(b){const list=b.highlights||[];return `<div class="card page-card hl-card"><div class="hl-head"><label>${icon('marker')}Altını çizdiklerim</label>${list.length?`<span class="muted">${list.length}</span>`:''}</div>${list.length?list.map(h=>`<button class="hl" data-action="hl-edit" data-id="${attr(b.id)}" data-hl="${attr(h.id)}"><span class="hl-text">${esc(h.text)}</span>${h.page||h.note?`<span class="hl-meta">${h.page?'s. '+h.page:''}${h.page&&h.note?' · ':''}${esc(h.note||'')}</span>`:''}</button>`).join(''):'<p class="hl-empty">Beğendiğin cümleleri burada biriktir. Sayfanın fotoğrafını çekip cümleyi oradan da seçebilirsin.</p>'}<button class="btn outline full hl-add" data-action="hl-new" data-id="${attr(b.id)}">${icon('marker')}Altını çiz</button></div>`}
function highlightSheet(bookId,h){const b=find(bookId);if(!b)return;const page=h?h.page:(draft&&draft.id===b.id?Number(draft.page)||0:b.currentPage||0);showSheet(h?'Altı çizili cümle':'Altını çiz',`<form id="hl-form" data-id="${attr(bookId)}" data-hl="${attr(h?h.id:'')}"><label class="field"><span>Altını çizdiğin cümle</span><textarea name="text" required maxlength="4000" class="hl-input" placeholder="Kitaptaki cümleyi yaz ya da fotoğraftan seç…">${esc(h?h.text:'')}</textarea></label><div class="hl-photo"><span>Sayfanın fotoğrafından al</span><div><button type="button" class="shop-chip" data-action="hl-photo" data-source="camera">${icon('camera')}Fotoğraf çek</button><button type="button" class="shop-chip" data-action="hl-photo" data-source="gallery">${icon('photo')}Galeriden</button></div><div id="hl-lines"></div></div><div class="row">${input('page','Sayfa',page||'','number','min="0" max="100000" inputmode="numeric" placeholder="—"')}</div><label class="field"><span>Notun (isteğe bağlı)</span><textarea name="note" maxlength="2000" placeholder="Neden altını çizdin, sana ne düşündürdü?">${esc(h?h.note:'')}</textarea></label><p id="hl-error" class="error" role="alert"></p></form>`,`${h?`<button class="btn danger" data-action="hl-delete">${icon('trash')}Sil</button>`:''}<button class="btn" data-action="hl-save">${icon('check')}Kaydet</button>`,'highlight')}
// Blank lines separate passages in Notion, so one passage keeps single line breaks.
const fold=t=>String(t).replace(/\r/g,'').replace(/\n{2,}/g,'\n').trim();
async function saveHighlight(button){const f=document.getElementById('hl-form');if(!f.reportValidity())return;const v=Object.fromEntries(new FormData(f)),b={...find(f.dataset.id)},list=[...(b.highlights||[])],old=f.dataset.hl,page=Number(v.page)||0;if(page<0||page>100000){document.getElementById('hl-error').textContent='Sayfa numarası geçersiz.';return}const item={id:old||uid(),text:fold(v.text),page,note:fold(v.note||''),createdAt:old?(list.find(x=>x.id===old)||{}).createdAt||'':new Date().toISOString()};const i=list.findIndex(x=>x.id===old);if(i>=0)list[i]=item;else list.unshift(item);button.disabled=true;try{S=await native('save',{...b,highlights:list});closeSheet();render();toast(old?'Cümle güncellendi.':'Altını çizdin.')}catch(e){document.getElementById('hl-error').textContent=e.message}finally{button.disabled=false}}
async function highlightPhoto(source){const f=document.getElementById('hl-form');try{const r=await native('photo',{source,textOnly:true});if(!r||!r.lines)return;const box=document.getElementById('hl-lines');if(!box)return;box.innerHTML=r.lines.length?`<p class="muted">Altını çizdiğin satırlara sırayla dokun:</p><div class="ocr-lines">${r.lines.map(l=>`<button type="button" data-action="hl-line">${esc(l)}</button>`).join('')}</div>`:'<p class="note warn">Fotoğrafta yazı bulunamadı. Daha yakından ve düz çekmeyi dene.</p>'}catch(e){toast(e.message)}}
function detailPage(){const b=find(detailId);if(!b)return empty('Kitap bulunamadı','Bu kitap artık rafında değil.','home','Kitaplığıma dön');if(!draft||draft.id!==b.id)draft={id:b.id,page:b.currentPage||0,rating:b.rating||0,notes:b.notes||''};const total=b.totalPages||0,synced=S.connected&&b.syncStatus==='synced',pending=S.connected&&b.syncStatus==='pending';
  return `<div class="detail-top"><button class="icon-btn" data-action="back" aria-label="Geri">${icon('back')}</button><h1>Kitap detayı</h1><button class="icon-btn" data-action="menu" data-id="${attr(b.id)}" aria-label="Diğer işlemler">${icon('dots')}</button></div><div class="detail-hero">${cover(b)}</div><div class="detail-title"><h2>${esc(b.title)}</h2><div class="author">${esc(b.author||'Yazar belirtilmedi')}</div></div><button class="status-pill" data-action="status" data-id="${attr(b.id)}" aria-label="Raf: ${STATUS[b.status]}. Değiştirmek için dokun">${icon('book')}${STATUS[b.status]}${icon('arrow')}</button>${b.buyUrl?offerCard(b):`<button class="find-price" data-action="find-price" data-id="${attr(b.id)}">${icon('cart')}Fiyatını ve satın alma linkini bul</button>${shopLinks(b)}`}<div class="card page-card"><div class="page-line"><label for="page-input">Kaldığım sayfa</label><button class="icon-btn step" data-action="page-step" data-step="-1" aria-label="Bir sayfa geri">${icon('minus')}</button><input id="page-input" type="number" inputmode="numeric" min="0" max="${total||100000}" value="${draft.page}" aria-label="Kaldığın sayfa"><button class="icon-btn step" data-action="page-step" data-step="1" aria-label="Bir sayfa ileri">${icon('plus')}</button><span class="total">${total?'/ '+total:'sayfa'}</span></div>${total?`<div class="progress" style="margin:12px 0 0"><span style="width:${Math.min(100,Math.round(draft.page/total*100))}%"></span></div>`:''}</div><div class="card page-card"><div class="rating-line"><label>Puanım</label><div class="rating">${[1,2,3,4,5].map(n=>`<button class="${n<=draft.rating?'filled':''}" data-action="rate" data-rating="${n}" aria-label="${n} yıldız ver">${icon('star')}</button>`).join('')}</div></div></div><div class="card page-card notes-card"><label for="notes-input">Notlarım</label><textarea id="notes-input" maxlength="12000" placeholder="Aklında kalan bir cümle, küçük bir not…">${esc(draft.notes)}</textarea><div class="sync-line ${pending?'warn':''}">${icon(synced?'check':pending?'sync':'cloud')}${synced?'Notion ile eşitlendi':pending?'Eşitleme bekliyor':S.connected?'Eşitleniyor':'Telefonda kayıtlı'}</div></div>${b.startedAt||b.finishedAt?`<p class="muted">${b.startedAt?'Başlama: '+esc(b.startedAt):''}${b.finishedAt?' · Bitiş: '+esc(b.finishedAt):''}</p>`:''}${highlightsCard(b)}<button class="remove-book" data-action="delete-confirm" data-id="${attr(b.id)}">${icon('trash')}Bu kitabı raftan kaldır</button><p id="detail-error" class="error" role="alert"></p><div class="detail-actions"><button class="btn" data-action="save-detail">Değişiklikleri kaydet</button></div>`}
async function saveDetail(button){const b={...find(detailId)},page=Number(draft.page),err=document.getElementById('detail-error');if(!Number.isInteger(page)||page<0||(b.totalPages>0&&page>b.totalPages)){err.textContent='Geçerli bir sayfa numarası gir.';return}
  b.rating=draft.rating;b.notes=draft.notes;if(page!==(b.currentPage||0)){b.currentPage=page;if(b.status==='done'&&(!b.totalPages||page<b.totalPages)){b.status='reading';b.finishedAt=''}if(page>0&&b.status==='want')b.status='reading';if(page>0&&!b.startedAt)b.startedAt=today();if(b.totalPages>0&&page===b.totalPages){b.status='done';b.finishedAt=today()}}
  button.disabled=true;try{validate(b);S=await native('save',b);draft=null;render();toast('Kaydedildi.')}catch(e){err.textContent=e.message}finally{button.disabled=false}}
function assistantSetup(){const a=S.assistant||{};showSheet('PC sunucusunu bağla',`<p class="note">Kitap Danışmanı, PC’nde çalışan Kitaplığım sunucusu üzerinden Claude ile konuşur. Adresi ve anahtarı sunucunun <b>server/.env</b> dosyasından al. Anahtar telefonda şifreli saklanır.</p><form id="assistant-form">${input('url','Ev ağı adresi',a.url||'http://192.168.1.12:8790','url','required autocomplete="off" autocapitalize="none" spellcheck="false"')}${input('altUrl','Evin dışı için Tailscale adresi (isteğe bağlı)',a.altUrl||'http://100.68.128.112:8790','url','autocomplete="off" autocapitalize="none" spellcheck="false"')}${input('token','Sunucu anahtarı (APP_TOKEN)','','password',`${a.configured?'':'required '}autocomplete="off" autocapitalize="none" spellcheck="false" placeholder="${a.configured?'Değiştirmeyeceksen boş bırak':''}"`)}<p id="assistant-error" class="error" role="alert"></p></form>`,`<button class="btn secondary" data-action="close">Vazgeç</button><button class="btn" data-action="assistant-save">Kaydet ve dene</button>`,'assistant')}
async function saveAssistant(button){const f=document.getElementById('assistant-form');if(!f.reportValidity())return;const v=Object.fromEntries(new FormData(f)),err=document.getElementById('assistant-error');button.disabled=true;button.textContent='Deneniyor…';try{S=await native('assistantSave',v);render();try{await native('assistantTest');closeSheet();toast('Kitap Danışmanı bağlandı.')}catch(e){err.textContent='Kaydedildi ama sunucuya ulaşılamadı: '+e.message}}catch(e){err.textContent=e.message}finally{button.disabled=false;button.textContent='Kaydet ve dene'}}
function render(){const bar=screen==='home'||screen==='detail',cls=bar?'has-bar':screen==='search'&&searchMode==='ai'&&S.assistant?.configured?'chat':'';const body=({home,search:searchPage,stats:statsPage,settings:settingsPage,detail:detailPage}[screen]||home)();app.innerHTML=`<main class="shell ${cls}">${screen==='detail'?'':header()}${body}</main>${screen==='home'?`<div class="add-bar"><button class="btn" data-action="search">${icon('plus')}Kitap ekle</button></div>`:''}${screen==='detail'?'':nav()}`}
function navigate(next){document.body.classList.remove('typing');screen=next;render();window.scrollTo(0,0)}
function empty(title,text,action='search',label='Kitap ekle'){return `<div class="empty">${icon('book')}<h3>${title}</h3><p>${text}</p><button class="btn small" data-action="${action}">${icon('plus')}${label}</button></div>`}
function statsPage(){const goal=Number(S.goals?.[S.profile]||0),done=annual(),books=profileBooks(),pages=books.reduce((n,b)=>n+(Number(b.currentPage)||0),0),rated=books.filter(b=>b.rating>0);return `${profiles()}<div class="page-title"><p>${new Date().getFullYear()} boyunca biriken sayfalar.</p></div><div class="panel" style="text-align:center"><h3>Bu yılki okuma yolculuğun</h3><div class="goal-ring" style="--value:${goal?Math.min(100,done/goal*100):0}"><div><strong>${done}</strong><small>${goal?'/ '+goal+' kitap':'kitap tamamladın'}</small></div></div><p>${goal?`${Math.max(0,goal-done)} kitap daha, hedefe bir adım daha.`:'Kendine ulaşılabilir bir yıllık hedef belirle.'}</p><button class="btn secondary small" data-action="goal">${goal?'Hedefi düzenle':'Hedef belirle'}</button><div class="muted" style="margin-top:12px">Bitiş tarihi bu yıl olan kitaplar sayılır.</div></div><div class="stats-strip"><div class="mini-stat"><strong>${count('done')}</strong><span>toplam biten kitap</span></div><div class="mini-stat"><strong>${pages.toLocaleString('tr-TR')}</strong><span>kayıtlı okunan sayfa</span></div><div class="mini-stat"><strong>${rated.length?(rated.reduce((s,b)=>s+b.rating,0)/rated.length).toFixed(1):'—'}</strong><span>ortalama puanın</span></div></div><div class="section-head"><h2>Ailece okuyoruz</h2><span class="muted">Bu yıl biten</span></div><div class="panel">${PROFILES.map(p=>{const n=annual(p),max=Math.max(1,...PROFILES.map(annual));return `<div class="family-line">${avatar(p,'sm')}<span style="font-size:11px;min-width:48px">${p}</span><div class="track"><span style="width:${n/max*100}%"></span></div><small>${n} kitap</small></div>`}).join('')}</div>`}
function assistantPanel(){const a=S.assistant||{};return `<div class="panel"><h3>${icon('sparkle')}Kitap Danışmanı</h3><p>${a.configured?'PC’deki Claude ile konuşarak kitap bulur ve öneri verir.':'PC’de çalışan sunucuya bağlanınca kitap bulma ve öneri sohbeti açılır.'}</p>${a.configured?`<div class="list-item"><strong>Sunucu</strong><span>${esc(a.url)}</span></div>${a.altUrl?`<div class="list-item"><strong>Yedek adres</strong><span>${esc(a.altUrl)}</span></div>`:''}`:''}<div class="row" style="margin-top:14px"><button class="btn" data-action="assistant-setup">${a.configured?'Ayarları düzenle':'PC sunucusunu bağla'}</button>${a.configured?'<button class="btn secondary" data-action="assistant-test">Bağlantıyı dene</button>':''}</div>${a.configured?'<button class="tiny-link" data-action="assistant-clear" style="margin-top:18px">Bu telefondaki bağlantıyı kaldır</button>':''}</div>`}
function settingsPage(){const pending=S.books.filter(b=>b.syncStatus==='pending').length,cs=conflicts();return `<div class="page-title"><p>Aile profilleri, Kitap Danışmanı ve Notion bağlantısı.</p></div>${assistantPanel()}<div class="panel"><h3>${icon('cloud')}Notion’daki kitaplığın</h3><p>${S.connected?'Kitaplar ve değişiklikler iki yönde eşitlenir. Uygulama açıkken ve uygun koşullarda arka planda kontrol edilir.':'Notion bağlantısını kurduğunda hem buradan hem Notion’dan kitap ekleyip düzenleyebilirsin.'}</p><div class="list-item"><strong>Bağlantı</strong><span>${S.connected?'Bağlı':'Henüz kurulmadı'}</span></div><div class="list-item"><strong>Aktarım bekleyen</strong><span>${pending} kayıt</span></div>${S.lastSync?`<div class="list-item"><strong>Son eşitleme</strong><span>${esc(new Date(S.lastSync).toLocaleString('tr-TR',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}))}</span></div>`:''}${S.syncError?`<p class="error">${esc(S.syncError)}</p>`:''}<div class="row" style="margin-top:17px"><button class="btn" data-action="${S.connected?'sync':'connect'}">${icon('sync')}${S.connected?'Şimdi eşitle':'Notion’u bağla'}</button><button class="btn secondary" data-action="open-notion">Kitaplığı aç</button></div>${S.connected?'<button class="tiny-link" data-action="disconnect" style="margin-top:20px">Bu telefondaki bağlantıyı kaldır</button>':''}</div>${cs.length?`<div class="panel"><h3>${icon('alert')}İki yerde değişen kitaplar</h3><p>İki sürüm de korunuyor. Hangisinin kalacağını seç.</p>${cs.map(b=>`<button class="result" data-action="conflict" data-id="${attr(b.id)}"><div class="result-info"><h3>${esc(b.title)}</h3><p>${esc(b.profile)}</p></div>${icon('arrow')}</button>`).join('')}</div>`:''}<div class="panel"><h3>${icon('heart')}Aile kitaplığımız</h3><p>Profillerin kitapları ayrı tutulur. Aynı kitabı farklı kişiler kendi ilerlemeleriyle ekleyebilir.</p>${PROFILES.map(p=>`<div class="list-item">${avatar(p,'sm')}<strong>${p}</strong><span>${profileBooks(p).length} kitap</span></div>`).join('')}<div class="note">Profiller arasında parola yoktur. Bu kitaplığa erişen kişiler tüm aile kayıtlarını görebilir.</div></div><div class="panel"><h3>${icon('download')}Bilgilerini dışa aktar</h3><p>Kitap bilgilerini ve notlarını JSON dosyası olarak paylaşabilirsin. Fotoğraflar bu dosyaya dahil edilmez.</p><button class="btn secondary" data-action="export">Dışa aktar</button></div><div class="note">İnternet yokken kitap ekleyebilir ve ilerlemeni güncelleyebilirsin. Notion aktarımı bağlantı gelince devam eder. Android pil ayarları arka plan eşitlemesini geciktirebilir.</div><div class="footer-note">KİTAPLIĞIM · 1.1.0 · AİLEMİZE AİT BİR KÖŞE</div>`}
function showSheet(title,body,footer='',name='generic'){modalName=name;modal.innerHTML=`<div class="modal-backdrop"><section class="sheet" role="dialog" aria-modal="true" aria-label="${attr(title)}"><header class="sheet-head"><h2>${title}</h2><button class="icon-btn" data-action="close" aria-label="Kapat">${icon('close')}</button></header><div class="sheet-body">${body}</div>${footer?`<footer class="sheet-footer">${footer}</footer>`:''}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>modal.querySelector('input,button')?.focus(),50)}
function closeSheet(){modal.innerHTML='';modalName='';document.body.style.overflow=''}
function find(id){return S.books.find(b=>b.id===id)}
function input(name,label,value='',type='text',extra=''){return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${attr(value)}" ${extra}></label>`}
function captureEdit(){const f=document.getElementById('edit-form');if(!f||!editBook)return;const v=Object.fromEntries(new FormData(f));editBook={...editBook,...v,totalPages:Number(v.totalPages)||0,currentPage:Number(v.currentPage)||0,rating:Number(v.rating)||0}}
function edit(b={}){editBook={profile:S.profile,status:'want',title:'',author:'',isbn:'',cover:'',totalPages:0,currentPage:0,notes:'',rating:0,startedAt:'',finishedAt:'',photoKey:'',price:'',store:'',buyUrl:'',...b};if(pendingPhoto&&!b.id)Object.assign(editBook,{localCover:pendingPhoto.localCover,photoKey:pendingPhoto.photoKey});selectedRating=editBook.rating;const x=editBook,token=++offerToken,lookup=!x.id&&!x.buyUrl&&!!(x.isbn||x.title);if(lookup)x.offerPending=true;
  const shelves=[['want','Okuyacaklarım','shelf'],['reading','Okuyorum','book'],['done','Okuduklarım','stack'],['paused','Ara verdim','minus']];
  const finder=x.id?'':`<form id="sheet-search" class="search-box add-search">${icon('search')}<input name="q" placeholder="Kitap adı, yazar veya ISBN" aria-label="Kitap adı, yazar veya ISBN" enterkeyhint="search" autocomplete="off"></form><div class="add-tools"><button type="button" class="add-tool" data-action="photo-options">${icon('camera')}Kapaktan bul</button><button type="button" class="add-tool" data-action="photo-options">${icon('barcode')}ISBN tara</button></div>`;
  showSheet(x.id?'Kitabı düzenle':'Kitap ekle',`${finder}<form id="edit-form" class="add-form"><div class="book-card"><div class="book-card-cover">${cover(x)}<button type="button" class="cover-cam" data-action="attach-photo" aria-label="Kapak fotoğrafı ekle">${icon('camera')}</button></div><div class="book-card-fields"><label class="field"><span>Kitap adı</span><input name="title" value="${attr(x.title)}" required maxlength="400" autocomplete="off"></label><label class="field"><span>Yazar</span><input name="author" value="${attr(x.author)}" maxlength="400"></label><button type="button" class="text-btn edit-more" data-action="open-more">${icon('edit')}Kapak ve bilgileri düzenle</button>${x.localCover?`<button type="button" class="tiny-link photo-remove" data-action="remove-photo">${icon('close')}Fotoğrafı kaldır</button>`:''}</div></div><div id="offer-slot">${offerCard(x)}</div><h3 class="add-h">Kimin kitabı?</h3><div class="who-row">${PROFILES.map(p=>`<label class="who"><input type="radio" name="profile" value="${attr(p)}" ${p===x.profile?'checked':''}><span class="who-ring">${avatar(p)}<i class="tick">${icon('check')}</i></span><span>${esc(p)}</span></label>`).join('')}</div><h3 class="add-h">Hangi rafta?</h3><div class="shelf-grid">${shelves.map(([id,name,ic])=>`<label class="shelf-tile"><input type="radio" name="status" value="${id}" ${x.status===id?'checked':''}><i class="tick">${icon('check')}</i>${icon(ic)}<span>${name}</span></label>`).join('')}</div><div class="row pages">${input('totalPages','Toplam sayfa',x.totalPages||'','number','min="0" max="100000" inputmode="numeric" placeholder="Bilinmiyor"')}${input('currentPage','Kaldığım sayfa',x.currentPage||'','number','min="0" max="100000" inputmode="numeric" placeholder="0"')}</div><details class="more" id="more"><summary>${icon('sliders')}<span class="more-text"><strong>Diğer bilgiler</strong><small>Tarihler, puan, not, fiyat ve satın alma linki</small></span>${icon('chevron')}</summary><div class="row">${input('startedAt','Başlama',x.startedAt,'date')}${input('finishedAt','Bitiş',x.finishedAt,'date')}</div><div class="field"><span>Puanın</span><input type="hidden" name="rating" value="${x.rating||0}"><div class="rating" role="group" aria-label="Puan">${[1,2,3,4,5].map(n=>`<button type="button" class="${n<=(x.rating||0)?'filled':''}" data-action="edit-rate" data-rating="${n}" aria-label="${n} yıldız">${icon('star')}</button>`).join('')}</div></div><label class="field"><span>Notların</span><textarea name="notes" maxlength="12000" placeholder="Aklında kalan bir cümle, küçük bir not…">${esc(x.notes)}</textarea></label>${input('price','Fiyat',x.price,'text','maxlength="40" placeholder="ör. 231,00 TL"')}${input('buyUrl','Satın alma linki',x.buyUrl,'url','maxlength="2000" placeholder="https://…"')}${input('isbn','ISBN',x.isbn,'text','maxlength="30"')}${input('cover','Kapak adresi',x.cover,'url','placeholder="https://…"')}</details><p id="form-error" class="error" role="alert"></p></form>`,`<button class="btn add-submit" data-action="save-edit">${icon(x.id?'check':'bookplus')}${x.id?'Değişiklikleri kaydet':'Kitaplığıma ekle'}</button>`,'edit');if(lookup)fetchOffer(token);if(!x.id)loadShopPrices(x,true)}
async function attachPhoto(source){captureEdit();const keep=editBook;closeSheet();try{const p=await native('photo',{source});if(p.localCover)Object.assign(keep,{localCover:p.localCover,photoKey:p.photoKey})}catch(e){toast(e.message)}edit(keep)}
function conflict(b){const r=b.conflictRemote;const info=x=>`<strong>${esc(x.title)}</strong>${esc(x.author)}<br>${esc(x.profile)} · ${STATUS[x.status]||x.status}<br>${x.currentPage||0} / ${x.totalPages||'?'} sayfa · ${x.rating||0} yıldız${x.deleted?'<br>Silinmek üzere işaretli':''}${x.isbn?'<br>ISBN: '+esc(x.isbn):''}${x.startedAt?'<br>Başlama: '+esc(x.startedAt):''}${x.finishedAt?'<br>Bitiş: '+esc(x.finishedAt):''}${x.notes?'<br>Not: '+esc(x.notes):''}`;showSheet('İki sürümü karşılaştır',`<p class="note warn">Bu kitap telefonda ve Notion’da ayrı ayrı değişti. Seçtiğin sürüm diğer tarafa da yansıtılır.</p><h3>Telefondaki</h3><div class="conflict-card">${info(b)}</div><h3>Notion’daki</h3><div class="conflict-card">${info(r)}</div>`,`<button class="btn secondary" data-action="resolve-local" data-id="${attr(b.id)}">Telefondaki kalsın</button><button class="btn" data-action="resolve-remote" data-id="${attr(b.id)}">Notion’daki kalsın</button>`,'conflict')}
function connect(){showSheet('Notion’u bağla',`<p class="note">Bu işlem bir kez yapılır. Bağlantı anahtarını yalnız bu uygulamaya gir; sohbet mesajına yazmana gerek yok.</p><ol style="padding-left:20px;font-size:12px;line-height:1.8;color:#83735c"><li>Notion’da çalışma alanın için bir dahili bağlantı oluştur. İçeriği okuma, ekleme ve güncelleme yetkileri açık olsun.</li><li>“Aile Kitaplığımız” sayfasını aç. Sayfa menüsündeki Bağlantılar bölümünden oluşturduğun bağlantıyı ekle.</li><li>Bağlantının gizli anahtarını aşağıya yapıştır.</li></ol><div class="row"><button class="btn secondary small" data-action="open-integrations">Bağlantı oluştur</button><button class="btn secondary small" data-action="open-notion">Kitaplığı aç</button></div><form id="connect-form">${input('token','Notion bağlantı anahtarı','','password','required autocomplete="off" autocapitalize="none" spellcheck="false"')}<p class="muted">Anahtar telefonun güvenli anahtarıyla şifrelenir. APK’nın içine gömülmez.</p><p id="connect-error" class="error" role="alert"></p></form>`,`<button class="btn secondary" data-action="close">Daha sonra</button><button class="btn" data-action="save-connection">Bağlantıyı kur</button>`,'connect')}
function photoOptions(){showSheet('Kitabının fotoğrafını ekle',`<p class="note">Ön kapağı net ve düz çek; kitap ve yazar adı görünür olsun. Arka kapaktaki ISBN barkodunu da kullanabilirsin.</p><button class="btn full" data-action="photo-camera" style="margin:12px 0">${icon('camera')}Kamerayla çek</button><button class="btn full secondary" data-action="photo-gallery">${icon('photo')}Galeriden seç</button><p class="muted" style="margin-top:18px">Fotoğraftaki yazı ve barkod telefonda okunur. Kitap bilgilerini aramak için internet kullanılır.</p>`,'','photo-options')}
async function getPhoto(source){closeSheet();toast('Fotoğraf seçilince kapaktaki yazı okunacak…');try{const p=await native('photo',{source});if(!p.localCover)return;pendingPhoto=p;const suggestion=p.isbn||(p.suggestions||[]).slice(0,2).join(' ');showSheet('Kapakta ne yazıyor?',`<div class="photo-preview"><img src="https://appassets.androidplatform.net/covers/${attr(p.localCover)}" alt="Eklenen fotoğraf"><p class="muted">Kitap adını kontrol edip düzelt. Birden fazla satır varsa adını birleştirebilirsin.</p></div><form id="ocr-form">${input('q','Kitap adı veya ISBN',suggestion,'text','required')}<p class="muted">Bir satıra dokunarak arama kutusuna al:</p><div class="ocr-lines" style="margin-top:12px">${(p.suggestions||[]).map((line,i)=>`<button type="button" data-action="ocr-line" data-index="${i}">${esc(line)}</button>`).join('')}</div>${!p.text?'<p class="note warn">Yazı bulunamadı. Kitap adını kendin yazabilir, fotoğrafı kapak olarak kullanabilirsin.</p>':''}</form>`,`<button class="btn secondary" data-action="ocr-manual">Elle tamamla</button><button class="btn" data-action="ocr-search">Kitabı bul</button>`,'ocr')}catch(e){toast(e.message)}}
async function doSearch(q){searchQuery=q.trim();if(searchQuery.length<2){toast('En az 2 karakter yaz.');return}searching=true;searchError='';results=[];searchMode='find';navigate('search');try{results=await native('search',{q:searchQuery})}catch(e){searchError=e.message}finally{searching=false;if(screen==='search')render()}loadOffers()}
async function loadOffers(){const list=results,targets=list.filter(b=>!b.price&&b.isbn).slice(0,12);if(!targets.length)return;targets.forEach(b=>b.offerPending=true);if(screen==='search')render();let found=[];try{found=await native('offers',{books:targets.map(b=>({isbn:b.isbn,title:b.title,author:b.author}))})}catch{}targets.forEach((b,i)=>{delete b.offerPending;const o=found[i];if(o&&o.price&&o.buyUrl)Object.assign(b,{price:o.price,store:o.store,buyUrl:o.buyUrl})});if(results===list&&screen==='search'&&searchMode==='find')render()}
const SHOPS=[['İdefix','https://www.idefix.com/arama?q='],['Trendyol','https://www.trendyol.com/sr?q='],['Hepsiburada','https://www.hepsiburada.com/ara?q='],['D&R','https://www.dr.com.tr/search?q=']];
const shopCache=new Map();
function shopQuery(x){const isbn=String(x.isbn||'').replace(/[^0-9Xx]/g,'');return (isbn.length===10||isbn.length===13?isbn:[x.title,x.author].filter(Boolean).join(' ')).trim()}
function amount(p){const n=Number(String(p||'').replace(/[^\d,]/g,'').replace(',','.'));return n>0?n:Infinity}
function shopLinks(x){const q=shopQuery(x);if(!q)return '';const got=shopCache.get(q),list=[...(Array.isArray(got)?got:[]),...(x.others||[])],pending=got==='pending',best=Math.min(amount(x.price),...list.map(o=>amount(o.price)));
  const chips=SHOPS.filter(([n])=>!(x.store||'').startsWith(n)).map(([n,u])=>{const o=list.find(o=>o.store===n);if(o)return `<button type="button" class="shop-chip priced ${amount(o.price)===best?'best':''}" data-action="buy" data-url="${attr(o.buyUrl)}">${esc(n)}<strong>${esc(o.price)}</strong>${icon('external')}</button>`;return `<button type="button" class="shop-chip" data-action="buy" data-url="${attr(u+encodeURIComponent(q))}">${esc(n)}${pending&&(n==='Trendyol'||n==='Hepsiburada')?'<span class="chip-dots">…</span>':''}${icon('external')}</button>`}).join('')+list.filter(o=>o.store!==x.store&&!SHOPS.some(([n])=>n===o.store)).map(o=>`<button type="button" class="shop-chip priced ${amount(o.price)===best?'best':''}" data-action="buy" data-url="${attr(o.buyUrl)}">${esc(o.store)}<strong>${esc(o.price)}</strong>${icon('external')}</button>`).join('');
  return `<div class="shop-links" data-q="${attr(q)}"><span>${pending?'Diğer mağazaların fiyatlarına bakılıyor…':list.length?'Diğer mağazalar':'Diğer mağazalarda bak'}</span><div>${chips}</div></div>`}
function refreshShops(){if(modalName==='edit'&&editBook){const el=document.getElementById('offer-slot');if(el)el.innerHTML=offerCard(editBook)}else if(screen==='detail'){const b=find(detailId),el=document.querySelector('.shop-links');if(b&&el)el.outerHTML=shopLinks(b)}}
// Cheapest known offer becomes the link that gets saved with a new book.
function applyCheapest(x){const list=shopCache.get(shopQuery(x));if(!Array.isArray(list)||x.offerPending)return;let best=null;for(const o of list)if(amount(o.price)<amount(x.price))best=o;if(best){if(x.price&&x.buyUrl)x.others=[{store:x.store,price:x.price,buyUrl:x.buyUrl}];Object.assign(x,{price:best.price,store:best.store,buyUrl:best.buyUrl,searchOnly:false});const f=document.getElementById('edit-form');if(f&&editBook===x){f.elements.price.value=x.price;f.elements.buyUrl.value=x.buyUrl}}}
async function loadShopPrices(x,isNew){const q=shopQuery(x);if(!q)return;if(!shopCache.has(q)){shopCache.set(q,'pending');refreshShops();let list=[];try{list=await native('shopPrices',{isbn:x.isbn||'',title:x.title||'',author:x.author||''})}catch{}shopCache.set(q,Array.isArray(list)?list:[])}if(isNew&&editBook===x)applyCheapest(x);refreshShops()}
function offerCard(x){if(x.offerPending)return `<div class="offer-card pending"><span class="offer-spinner"></span><div class="offer-text"><strong>Fiyat aranıyor…</strong><span class="offer-store">Kitapçılara bakılıyor</span></div></div>${shopLinks(x)}`;if(!x.buyUrl)return shopLinks(x);const search=x.searchOnly||(!x.price&&/araması$/.test(x.store||''));return `<div class="offer-card ${search?'search':''}"><div class="offer-icon">${icon('cart')}</div><div class="offer-text">${x.price?`<strong>${esc(x.price)}</strong><span class="offer-store">${esc(x.store||'Satış sayfası')}</span>`:`<strong>Fiyat bulunamadı</strong><span class="offer-store">Mağazada aramak için dokun</span>`}</div><button type="button" class="btn small" data-action="buy" data-url="${attr(x.buyUrl)}">${search?'Mağazada ara':'Satın al'}${icon('external')}</button></div>${shopLinks(x)}`}
async function fetchOffer(token){const x=editBook;x.offerPending=true;const slot=document.getElementById('offer-slot');if(slot)slot.innerHTML=offerCard(x);let o={};try{o=(await native('offers',{books:[{isbn:x.isbn||'',title:x.title||'',author:x.author||''}]}))[0]||{}}catch{}if(token!==offerToken||editBook!==x)return;delete x.offerPending;if(o.buyUrl)Object.assign(x,{price:o.price||'',store:o.store||'',buyUrl:o.buyUrl,searchOnly:!!o.searchOnly});applyCheapest(x);if(modalName!=='edit')return;const f=document.getElementById('edit-form');if(f){f.elements.price.value=x.price||'';f.elements.buyUrl.value=x.buyUrl||''}const el=document.getElementById('offer-slot');if(el)el.innerHTML=offerCard(x)}
function validate(b){if(!b.title.trim())throw Error('Kitap adını yaz.');if(b.totalPages<0||b.currentPage<0)throw Error('Sayfa sayısı negatif olamaz.');if(b.totalPages&&b.currentPage>b.totalPages)throw Error('Kaldığın sayfa toplam sayfayı geçemez.');if(b.startedAt&&b.finishedAt&&b.finishedAt<b.startedAt)throw Error('Bitiş tarihi başlangıçtan önce olamaz.');if(b.cover&&!b.cover.startsWith('https://'))throw Error('Kapak adresi https ile başlamalı.');if(b.buyUrl&&!b.buyUrl.startsWith('https://'))throw Error('Satın alma linki https ile başlamalı.')}
async function saveEdit(button){const form=document.getElementById('edit-form');if(!form.reportValidity())return;const values=Object.fromEntries(new FormData(form)),b={...editBook,...values,price:(values.price||'').trim(),buyUrl:(values.buyUrl||'').trim(),totalPages:Number(values.totalPages)||0,currentPage:Number(values.currentPage)||0,rating:Number(values.rating)||0};if(b.buyUrl!==(editBook.buyUrl||'')||!b.buyUrl)b.store='';delete b.offerPending;delete b.searchOnly;delete b.others;try{validate(b);if(b.status==='reading'&&!b.startedAt)b.startedAt=today();if(b.status==='done'){if(!b.finishedAt)b.finishedAt=today();if(b.totalPages)b.currentPage=b.totalPages}button.disabled=true;S=await native('save',b);pendingPhoto=null;draft=null;closeSheet();render();toast('Kitap rafına kaydedildi.')}catch(e){document.getElementById('form-error').textContent=e.message}finally{button.disabled=false}}
document.addEventListener('input',e=>{const t=e.target;if(t.closest('#book-search')&&t.name==='q')searchQuery=t.value;if(t.closest('#library-search')&&t.name==='q')libraryQuery=t.value;if(t.closest('#chat-form')){chatDraft=t.value;t.style.height='auto';t.style.height=Math.min(130,t.scrollHeight)+'px'}if(draft&&screen==='detail'){if(t.id==='page-input'){draft.page=t.value===''?0:Number(t.value);updateDetailProgress()}if(t.id==='notes-input')draft.notes=t.value}});
document.addEventListener('focusin',e=>{if(e.target.closest?.('.chat-form'))document.body.classList.add('typing')});
document.addEventListener('focusout',e=>{if(e.target.closest?.('.chat-form'))setTimeout(()=>{if(!document.activeElement?.closest?.('.chat-form'))document.body.classList.remove('typing')},60)});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&e.target.matches?.('.chat-form textarea')){e.preventDefault();e.target.form.requestSubmit()}});
document.addEventListener('error',e=>{if(e.target.tagName==='IMG')e.target.remove()},true);
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;try{if(form.id==='book-search')await doSearch(new FormData(form).get('q'));if(form.id==='sheet-search'){const q=new FormData(form).get('q');closeSheet();await doSearch(q)}if(form.id==='library-search'){libraryQuery=new FormData(form).get('q').trim();render()}if(form.id==='edit-form')await saveEdit(modal.querySelector('[data-action="save-edit"]'));if(form.id==='hl-form')await saveHighlight(modal.querySelector('[data-action="hl-save"]'));if(form.id==='ocr-form')await doSearchFromOcr();if(form.id==='connect-form')await saveConnection(modal.querySelector('[data-action="save-connection"]'));if(form.id==='assistant-form')await saveAssistant(modal.querySelector('[data-action="assistant-save"]'));if(form.id==='chat-form')await sendChat(new FormData(form).get('m'));if(form.id==='goal-form'){const n=Number(new FormData(form).get('goal'));if(!Number.isInteger(n)||n<1||n>1000){toast('1–1000 arasında bir hedef gir.');return}S=await native('settings',{goal:n});closeSheet();render();toast('Yıllık hedefin kaydedildi.')}}catch(err){toast(err.message)}});
async function doSearchFromOcr(){const q=modal.querySelector('[name=q]').value;closeSheet();await doSearch(q)}
async function saveConnection(button){const input=modal.querySelector('[name=token]');const token=input.value.trim();if(!token){document.getElementById('connect-error').textContent='Bağlantı anahtarını gir.';return}button.disabled=true;button.textContent='Kontrol ediliyor…';try{S=await native('connect',{token});input.value='';closeSheet();render();toast('Notion bağlantısı kuruldu. Eşitleme başlıyor.')}catch(e){document.getElementById('connect-error').textContent=e.message}finally{button.disabled=false;button.textContent='Bağlantıyı kur'}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;try{switch(a){
case'nav':navigate(b.dataset.screen);break;case'home':case'stats':case'settings':navigate(a);break;case'search':searchMode='find';navigate('search');break;
case'mode':searchMode=b.dataset.mode;render();break;
case'shelf':shelf=b.dataset.shelf;libraryQuery='';render();break;
case'back':leaveDetail();break;case'leave-now':closeSheet();draft=null;navigate(detailFrom);break;
case'menu':showSheet('Kitap işlemleri',`<div class="menu-list"><button data-action="menu-edit" data-id="${attr(id)}">${icon('edit')}Bilgileri düzenle</button><button class="danger-text" data-action="delete-confirm" data-id="${attr(id)}">${icon('trash')}Kitabı kaldır</button></div>`,'','menu');break;
case'menu-edit':closeSheet();edit(find(id));break;
case'status':{const cur=find(id);showSheet('Hangi rafta?',`<div class="menu-list">${Object.entries(STATUS).map(([k,v])=>`<button data-action="set-status" data-id="${attr(id)}" data-status="${k}">${icon(cur.status===k?'check':'book')}${v}</button>`).join('')}<button class="danger-text" data-action="delete-confirm" data-id="${attr(id)}">${icon('trash')}Raftan kaldır</button></div>`,'','status');break}
case'set-status':{const book={...find(id),status:b.dataset.status};if(book.status==='reading'&&!book.startedAt)book.startedAt=today();if(book.status==='done'){if(!book.finishedAt)book.finishedAt=today();if(book.totalPages)book.currentPage=book.totalPages}S=await native('save',book);if(draft)draft.page=find(id).currentPage||0;closeSheet();render();toast('Raf güncellendi.');break}
case'page-step':{const field=document.getElementById('page-input'),cur=find(detailId);let v=Math.max(0,(Number(field.value)||0)+Number(b.dataset.step));if(cur.totalPages)v=Math.min(v,cur.totalPages);field.value=v;draft.page=v;updateDetailProgress();break}
case'rate':{const n=Number(b.dataset.rating);draft.rating=draft.rating===n?0:n;render();break}
case'save-detail':await saveDetail(b);break;
case'assistant-setup':assistantSetup();break;case'assistant-save':await saveAssistant(b);break;
case'assistant-test':try{await native('assistantTest');toast('Sunucuya ulaşıldı.')}catch(err){toast(err.message)}break;
case'assistant-clear':S=await native('assistantClear');render();toast('Bu telefondaki danışman bağlantısı kaldırıldı.');break;
case'chat-idea':await sendChat(b.dataset.text);break;
case'chat-retry':await requestChat(S.profile);break;
case'chat-clear':saveChat([]);chatError='';render();break;
case'rec-add':{const r=loadChat()[Number(b.dataset.msg)]?.books?.[Number(b.dataset.book)];if(r)edit({title:r.title,author:r.author,isbn:r.isbn||'',cover:r.cover||'',totalPages:r.totalPages||0,status:'want',...(r.buyUrl?{price:r.price||'',store:r.store||'',buyUrl:r.buyUrl}:{})});break}
case'profile':S=await native('settings',{profile:b.dataset.profile});render();break;
case'close':if(modalName==='edit'&&editBook){const draft=Object.fromEntries(new FormData(document.getElementById('edit-form')));editBook={...editBook,...draft,totalPages:Number(draft.totalPages)||0,currentPage:Number(draft.currentPage)||0,rating:Number(draft.rating)||0};showSheet('Değişikliklerden vazgeçilsin mi?','<p class="note">Kaydetmediğin düzenlemeler kapatılacak.</p>','<button class="btn secondary" data-action="keep-editing">Düzenlemeye dön</button><button class="btn" data-action="discard-edit">Vazgeç</button>','discard')}else closeSheet();break;
case'keep-editing':edit(editBook);break;case'discard-edit':closeSheet();break;
case'manual':edit(pendingPhoto?{isbn:pendingPhoto.isbn||''}:{});break;
case'edit':edit(find(id));break;case'detail':openDetail(id);break;case'select-result':edit(results[Number(b.dataset.index)]);break;
case'save-edit':await saveEdit(b);break;
case'hl-new':highlightSheet(id);break;
case'hl-edit':{const book=find(id);highlightSheet(id,(book.highlights||[]).find(h=>h.id===b.dataset.hl));break}
case'hl-save':await saveHighlight(b);break;
case'hl-photo':await highlightPhoto(b.dataset.source);break;
case'hl-line':{const t=modal.querySelector('[name=text]');t.value=(t.value.trim()?t.value.trim()+' ':'')+b.textContent;b.classList.add('used');break}
case'hl-delete':{const f=document.getElementById('hl-form'),book={...find(f.dataset.id)};S=await native('save',{...book,highlights:(book.highlights||[]).filter(h=>h.id!==f.dataset.hl)});closeSheet();render();toast('Cümle silindi.');break}
case'open-more':{const d=document.getElementById('more');d.open=true;d.scrollIntoView({behavior:'smooth',block:'start'});break}
case'attach-photo':captureEdit();showSheet('Kapak fotoğrafı',`<div class="menu-list"><button data-action="attach-camera">${icon('camera')}Fotoğraf çek</button><button data-action="attach-gallery">${icon('photo')}Galeriden seç</button><button data-action="keep-editing">${icon('back')}Geri dön</button></div>`,'','attach');break;
case'attach-camera':await attachPhoto('camera');break;case'attach-gallery':await attachPhoto('gallery');break;
case'edit-rate':{const f=document.getElementById('edit-form'),cur=Number(f.elements.rating.value)||0,n=Number(b.dataset.rating),v=cur===n?0:n;f.elements.rating.value=v;f.querySelectorAll('[data-action=edit-rate]').forEach(x=>x.classList.toggle('filled',Number(x.dataset.rating)<=v));break}
case'buy':await native('openLink',{url:b.dataset.url});break;
case'find-price':{const cur=find(id);if(!cur)break;b.disabled=true;b.textContent='Fiyat aranıyor…';try{const o=(await native('offers',{books:[{isbn:cur.isbn||'',title:cur.title,author:cur.author||''}]}))[0]||{};if(!o.buyUrl){toast('Bu kitap için fiyat bulunamadı.');render();break}S=await native('save',{...find(id),price:o.price||'',store:o.store||'',buyUrl:o.buyUrl});render();toast(o.price?'Fiyat ve satın alma linki kaydedildi.':'Fiyat bulunamadı; mağaza araması kaydedildi.')}finally{b.disabled=false}break}
case'delete-confirm':{const book=find(id);showSheet('Kitap raftan kaldırılsın mı?',`<p class="note">${esc(book.title)} kaldırılacak. Notion bağlantısı varsa orada “Silindi” olarak işaretlenecek.</p>`,`<button class="btn secondary" data-action="close">Vazgeç</button><button class="btn danger" data-action="delete" data-id="${attr(id)}">Kitabı kaldır</button>`,'delete');break}
case'delete':S=await native('delete',{id});closeSheet();screen='home';draft=null;render();toast('Kitap kaldırıldı.');break;
case'connect':connect();break;case'save-connection':await saveConnection(b);break;
case'sync':b.disabled=true;b.innerHTML='Eşitleniyor…';try{S=await native('sync');toast(conflicts().length?'İki yerde değişen kitaplar var. Sürüm seçebilirsin.':'Notion ile eşitlendi.')}catch(err){S=await native('state');toast(err.message)}render();break;
case'disconnect':showSheet('Bağlantı kaldırılsın mı?','<p class="note">Bu telefonun Notion bağlantısı kaldırılır. Telefondaki kitaplar ve Notion’daki kayıtlar korunur.</p>','<button class="btn secondary" data-action="close">Vazgeç</button><button class="btn danger" data-action="disconnect-now">Bağlantıyı kaldır</button>');break;
case'disconnect-now':S=await native('disconnect');closeSheet();render();toast('Bu telefonun bağlantısı kaldırıldı.');break;
case'open-notion':await native('open',{url:DB_URL});break;case'open-integrations':await native('open',{url:'https://www.notion.so/profile/integrations'});break;
case'export':await native('export');break;
case'photo-options':photoOptions();break;case'photo-camera':await getPhoto('camera');break;case'photo-gallery':await getPhoto('gallery');break;
case'ocr-line':modal.querySelector('[name=q]').value=pendingPhoto.suggestions[Number(b.dataset.index)];break;
case'ocr-search':await doSearchFromOcr();break;case'ocr-manual':{const title=modal.querySelector('[name=q]').value;edit({title,isbn:pendingPhoto?.isbn||''});break}
case'remove-photo':{captureEdit();pendingPhoto=null;editBook.localCover='';editBook.photoKey='';edit(editBook);break}
case'goal':showSheet('Bu yıl kaç kitap olsun?',`<form id="goal-form"><p class="note">${esc(S.profile)} için yıllık hedef. İstediğin zaman değiştirebilirsin.</p>${input('goal','Kitap sayısı',S.goals?.[S.profile]||'','number','required min="1" max="1000" inputmode="numeric"')}</form>`,'<button class="btn full" data-action="save-goal">Hedefimi kaydet</button>','goal');break;
case'save-goal':document.getElementById('goal-form').requestSubmit();break;
case'conflict':conflict(find(id));break;case'resolve-local':case'resolve-remote':S=await native('resolve',{id,remote:a==='resolve-remote'});closeSheet();render();toast('Seçtiğin sürüm korundu.');break;
}}catch(err){toast(err.message)}});
window.onNativeBack=()=>{if(modalName){if(modalName==='edit')modal.querySelector('[data-action=close]').click();else closeSheet();return true}if(screen==='detail'){leaveDetail();return true}if(screen!=='home'){navigate('home');return true}return false};
native('state').then(data=>{S=data;render()}).catch(err=>{app.innerHTML=`<main class="shell"><div class="boot"><h1>Kitaplık açılamadı</h1><p class="error">${esc(err.message)}</p><p>Uygulamayı kapatıp yeniden aç.</p></div></main>`});
